/* HUNT READY 30 — Fit (v5.13). 15K run-walk plan with Strength A/B, run interval timer, four-slot fuel plan,
   hydration, supplement and medication log (user-reported only), weekly weight trend, insights, seed import.
   Loaded after camp.js and cycles.js, before app.js. Uses app.js globals at call time only. */

const FIT_VERSION='1.0';
// Compiled copy of seed/USER_SEED_DATA.json. Every value is an editable default, not a prescription.
// No investigational substance carries a dose or schedule here, on purpose.
const FIT_SEED={
  profile:{ heightIn:72, startWeight:250, goalWeight:225, lossMin:1, lossMax:1.5, baselineMi:[0.25,0.5],
    goals:['15K race readiness','bowhunting fitness','preserve muscle and strength','healthy active father'],
    race:{ distanceKm:15, distanceMi:9.32, window:'January-February 2027', date:null, mode:'runwalk' },
    cautions:['prior shoulder/labrum injury','prior neck-to-arm nerve symptoms'] },
  nutrition:{ calories:2400, protein:190, carbs:180, fat:102 },
  mealSlots:[ {key:'shake1',label:'Protein shake',time:'11:00'}, {key:'lunch',label:'Lunch',time:'13:30'}, {key:'shake2',label:'Protein shake',time:'16:00'}, {key:'dinner',label:'Dinner',time:'19:00'} ],
  foods:['eggs','ground beef','chicken breast','chicken thighs',"Trader Joe's chicken sausage","Trader Joe's chicken meatballs",'cottage cheese','Greek yogurt','cheese','plain frozen cut sweet potatoes','green beans','avocado','sourdough bread','ravioli (occasional)','olive oil','avocado oil','butter'],
  stores:["Trader Joe's",'Wild Fork','Sprouts','Publix'],
  prep:{ mainMeals:6, sweetPotatoPerMealG:175, greenBeansPerMealG:125 },
  days:{ Monday:'run_walk', Tuesday:'strength_A', Wednesday:'run_walk', Thursday:'recovery', Friday:'strength_B', Saturday:'long_run_walk', Sunday:'hunt_conditioning' },
  hydration:{ target:8, products:[ {name:'Water',sodium:0,potassium:0,magnesium:0}, {name:'LMNT',sodium:null,potassium:null,magnesium:null,note:'Enter the numbers from your packet.'}, {name:'Mountain Ops',sodium:null,potassium:null,magnesium:null,note:'Enter the numbers from your tub.'} ] },
  supps:[
    {name:'Creatine monohydrate',kind:'supplement',status:'planned',dose:'3–5',unit:'g',schedule:'daily',note:'Daily, any time. Plenty of water.'},
    {name:'Vitamin D3',kind:'supplement',status:'interested',dose:'',unit:'IU',schedule:'daily',note:'Dose not set. Add it from a lab result or your prescriber.'},
    {name:'Vitamin K2',kind:'supplement',status:'interested',dose:'',unit:'mcg',schedule:'daily',note:'Dose not set. Caution with warfarin or other blood thinners.'},
    {name:'Magnesium',kind:'supplement',status:'interested',dose:'',unit:'mg elemental',schedule:'daily',note:'Record the form (glycinate, citrate) and elemental mg from the label.'},
    {name:'Psyllium fiber',kind:'supplement',status:'owned',dose:'',unit:'servings',schedule:'daily',note:'Take with a full glass of water. Space it from oral medications per the label.'},
    {name:'Testosterone (TRT)',kind:'medication',status:'user_reported',concentration:200,weeklyMlMin:0.8,weeklyMlMax:0.9,dose:'',unit:'mL',schedule:'Mon/Wed/Fri',confirmed:false,note:'Logging reference only. The app never suggests a dose or a change. Reminders stay off until you confirm this is what your prescriber directed.'},
    {name:'Retatrutide',kind:'investigational',status:'considering',note:'Investigational. Not FDA approved. No dose or schedule is stored or suggested. Clinical-trial or clinician oversight only.'},
    {name:'Tesamorelin',kind:'investigational',status:'on_hold',note:'Considering, on hold. No stack, no timing, no dose.'},
    {name:'Ipamorelin',kind:'investigational',status:'on_hold',note:'Considering, on hold. No stack, no timing, no dose.'},
    {name:'BPC-157',kind:'investigational',status:'not_active',note:'Contemplated for the shoulder. Not validated for that use. Inactive.'},
    {name:'TB-500',kind:'investigational',status:'not_active',note:'Contemplated for the shoulder. Not validated for that use. Inactive.'},
    {name:'CJC-1295',kind:'investigational',status:'excluded',note:'Excluded by you. Kept here so it is not re-added by mistake.'}
  ]
};
const FIT_DAY_TYPES={ run_walk:'Run / walk', strength_A:'Strength A', strength_B:'Strength B', long_run_walk:'Long run / walk', recovery:'Recovery', hunt_conditioning:'Hunt conditioning', rest:'Rest' };
const FIT_SUPP_STATUS={ planned:'Planned', interested:'Interested', owned:'Owned', current:'Taking', user_reported:'User-reported', considering:'Considering', on_hold:'On hold', not_active:'Not active', excluded:'Excluded', stopped:'Stopped' };
// Run-walk ladder. Step 1 is the two-week starter. Every step up needs three sessions at the current step,
// seven pain-free days, decent readiness, and a tap from the user. Nothing advances on its own.
const FIT_RUN_STEPS=[
  {jog:60,walk:120,reps:8,label:'Jog 1 min · walk 2 min · 8 rounds'},
  {jog:90,walk:120,reps:7,label:'Jog 90 sec · walk 2 min · 7 rounds'},
  {jog:120,walk:120,reps:6,label:'Jog 2 min · walk 2 min · 6 rounds'},
  {jog:180,walk:120,reps:5,label:'Jog 3 min · walk 2 min · 5 rounds'},
  {jog:240,walk:120,reps:4,label:'Jog 4 min · walk 2 min · 4 rounds'},
  {jog:300,walk:120,reps:4,label:'Jog 5 min · walk 2 min · 4 rounds'},
  {jog:480,walk:120,reps:3,label:'Jog 8 min · walk 2 min · 3 rounds'},
  {jog:600,walk:120,reps:3,label:'Jog 10 min · walk 2 min · 3 rounds'},
  {jog:900,walk:120,reps:2,label:'Jog 15 min · walk 2 min · 2 rounds'},
  {jog:1200,walk:120,reps:2,label:'Jog 20 min · walk 2 min · 2 rounds'}
];
const FIT_RUN_SAFETY='Conversational pace. If you cannot talk, slow down. Stop and log it if anything hurts, goes numb, or shoots down an arm or leg.';

// ---------- state ----------
let fitEditingTypeVal=null; function fitSetEditingType(v){ fitEditingTypeVal=v||null; } function fitEditingType(){ return fitEditingTypeVal; }
function fitState(){ const s=STORE.get('hr30_fit',null); return s&&typeof s==='object'?s:null; }
function fitSave(s){ STORE.set('hr30_fit',s); }
function fitDefaults(){ const d=JSON.parse(JSON.stringify(FIT_SEED)); return { seeded:FIT_VERSION, plan:'hunter', profile:d.profile, mealSlots:d.mealSlots, foods:d.foods, stores:d.stores, prep:{...d.prep,items:[],resetAt:null}, days:d.days, hydration:{target:d.hydration.target,products:d.hydration.products}, hydrationLog:{}, savedMeals:fitDefaultMeals(d), supps:d.supps.map(x=>({id:uid(),taken:{},...x})), run:{step:1,approvals:[],stepSince:localDateKey()}, reminders:false, milestones:{} }; }
function fitDefaultMeals(d){ return [
  {id:uid(),name:'Protein shake',slot:'shake1',protein:0,calories:0,carbs:0,fat:0,portion:'Grams from your powder label. Set it once in Fuel → Saved meals.'},
  {id:uid(),name:'Protein shake',slot:'shake2',protein:0,calories:0,carbs:0,fat:0,portion:'Same shake as 11:00 unless you change it.'},
  {id:uid(),name:'Prep plate · chicken, sweet potato, green beans',slot:'lunch',protein:45,calories:0,carbs:0,fat:0,portion:`~${d.prep.sweetPotatoPerMealG} g sweet potato · ~${d.prep.greenBeansPerMealG} g green beans · protein portion to target`},
  {id:uid(),name:'Prep plate · ground beef, sweet potato, green beans',slot:'dinner',protein:45,calories:0,carbs:0,fat:0,portion:`~${d.prep.sweetPotatoPerMealG} g sweet potato · ~${d.prep.greenBeansPerMealG} g green beans · protein portion to target`},
  {id:uid(),name:'Eggs and sourdough',slot:'lunch',protein:30,calories:0,carbs:0,fat:0,portion:'Edit the eggs count and the slice. Log what you actually ate.'},
  {id:uid(),name:'Cottage cheese or Greek yogurt',slot:'dinner',protein:25,calories:0,carbs:0,fat:0,portion:'A tub serving. Protein from the label.'}
]; }
// Idempotent. Creates hr30_fit once; fills only the nutrition targets that are still zero. Never overwrites a value the user set.
function fitMigrate(){
  let s=fitState(), changed=false;
  if(!s){ s=fitDefaults(); changed=true; }
  else { const d=fitDefaults(); ['profile','mealSlots','foods','stores','prep','days','hydration','savedMeals','supps','run','milestones','hydrationLog'].forEach(k=>{ if(s[k]===undefined){ s[k]=d[k]; changed=true; } }); if(!s.plan){ s.plan='hunter'; changed=true; } }
  if(changed) fitSave(s);
  const t=STORE.get('hr30_nutritionTargets',{}); let tc=false; ['calories','protein','carbs','fat'].forEach(k=>{ if(!Number(t[k])){ t[k]=FIT_SEED.nutrition[k]; tc=true; } }); if(t.fiber===undefined){ t.fiber=0; tc=true; } if(tc) STORE.set('hr30_nutritionTargets',t);
}
function fitPlanOn(){ const s=fitState(); return !!s&&s.plan==='run15k'; }
function fitDayType(day){ const s=fitState(); return (s&&s.days&&s.days[day])||'rest'; }

// ---------- sessions ----------
function fitIntervalEx(step,opts={}){ const st=FIT_RUN_STEPS[Math.max(0,Math.min(FIT_RUN_STEPS.length-1,(step||1)-1))]; const warm=opts.warm??5, cool=opts.cool??5, walk=opts.walk??st.walk, reps=opts.reps??st.reps, jog=st.jog; const total=Math.round((warm*60+cool*60+reps*(jog+walk))/60);
  return {name:'Run / Walk Intervals',type:'intervals',warm,cool,jog,walk,reps,minutes:total,rest:0,prescription:`${warm} min walk · ${reps} × (jog ${fitSecLabel(jog)} + walk ${fitSecLabel(walk)}) · ${cool} min walk`,notes:`${FIT_RUN_SAFETY} The timer calls every jog and walk. Log distance by hand if you know it.`}; }
function fitSecLabel(sec){ return sec%60===0?`${sec/60} min`:sec<60?`${sec} sec`:`${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`; }
function fitSessionDef(type){ const s=fitState()||fitDefaults(), step=s.run?.step||1, pain=fitPainToday(), taper=fitTaper();
  const warm={name:'Warm-up',prescription:'5 min',type:'time',minutes:5,rest:0,notes:'Walk 2 min • bodyweight squat • hip hinge • reverse lunge • arm circles. Easy.'};
  const core={name:'Plank',prescription:'2 × 30 sec',type:'timed',sets:2,seconds:30,rest:30,notes:'Glutes tight, ribs down, breathe through the nose. Stop at a clean 30.'};
  const rpe='Two working sets, about RPE 6–7: you could do 3 or 4 more reps. Start light. Any shoulder or arm symptom means swap the movement or skip it.';
  switch(type){
    case 'run_walk': { const ex=pain?fitWalkOnly(30):fitIntervalEx(step); return {title:pain?'Easy Walk (pain logged)':'Run / Walk',focus:pain?'Walk only today · symptoms logged':FIT_RUN_STEPS[step-1].label,duration:ex.minutes,exercises:[ex]}; }
    case 'long_run_walk': { const reps=taper?Math.max(3,Math.round(FIT_RUN_STEPS[step-1].reps*0.6)):FIT_RUN_STEPS[step-1].reps+Math.min(2,step), ex=pain?fitWalkOnly(35):fitIntervalEx(step,{walk:Math.max(120,FIT_RUN_STEPS[step-1].walk+30),reps}); return {title:pain?'Easy Walk (pain logged)':taper?'Short Run / Walk · taper':'Long Run / Walk',focus:pain?'Walk only today · symptoms logged':`${ex.minutes} min · conversational · longer walks`,duration:ex.minutes,exercises:[ex]}; }
    case 'strength_A': return {title:'Strength A',focus:'Squat · hinge · supported row · core',duration:35,exercises:[warm,
      {name:'Goblet Squat',prescription:'2 × 8–10',type:'strength',sets:2,min:8,max:10,rest:75,notes:rpe},
      {name:'DB Romanian Deadlift',prescription:'2 × 8–10',type:'strength',sets:2,min:8,max:10,rest:75,notes:'Hips back, flat back, dumbbells slide down the thighs. '+rpe},
      {name:'1-Arm DB Row',prescription:'2 × 10/side',type:'strength',sets:2,min:10,max:10,rest:60,notes:'Chest or hand supported on a bench. Elbow to the hip, shoulder stays down. Stop the set if the neck or arm talks.'},
      core]};
    case 'strength_B': return {title:'Strength B',focus:'Step-up · split squat · pain-free push and pull · core',duration:35,exercises:[warm,
      {name:'Step-Up',prescription:'2 × 8/leg',type:'strength',sets:2,min:8,max:8,rest:60,notes:'Knee-height box or stair. Drive through the whole foot, control the way down. '+rpe},
      {name:'Split Squat',prescription:'2 × 8/leg',type:'strength',sets:2,min:8,max:8,rest:60,notes:'Front shin vertical, back knee toward the floor. Hold a wall for balance if you need it.'},
      {name:'DB Floor Press',prescription:'2 × 8–10',type:'strength',sets:2,min:8,max:10,rest:75,notes:'Elbows at 45°, pause on the floor. If the shoulder complains, push-ups on a counter instead. No overhead work.'},
      {name:'1-Arm DB Row',prescription:'2 × 10/side',type:'strength',sets:2,min:10,max:10,rest:60,notes:'Supported. Pull to the hip. Pain-free range only.'},
      core]};
    case 'recovery': return {title:'Recovery',focus:'Easy walk · mobility · rest is allowed',duration:30,optional:true,exercises:[
      {name:'Easy Walk / Cooldown',prescription:'20–30 min',type:'time',minutes:25,rest:0,notes:'A walk you could hold a conversation through. No pack.'},
      {name:'Mobility',prescription:'5 min',type:'time',minutes:5,rest:0,notes:'Calves, ankles, hips, hamstrings, thoracic rotation. Thirty seconds each.'}]};
    case 'hunt_conditioning': return {title:'Hunt Conditioning',focus:'Varied-terrain walk · light pack only if symptom-free',duration:40,optional:true,exercises:[
      {name:'Weighted Walk / Ruck',prescription:'30–45 min · varied terrain',type:'ruck',minutes:35,load:0,rest:0,notes:'Trails, hills, sand, whatever you have. Pack stays home unless you are fully symptom-free, and then light (10–15 lb). Full rest is a fine answer today.'}]};
    default: return {title:'Rest',focus:'Rest • family • easy movement',duration:0,exercises:[{name:'No structured training',prescription:'Recover',type:'rest',rest:0,notes:'Easy walking is fine. Recovery counts.'}]};
  }
}
function fitWalkOnly(min){ return {name:'Easy Walk / Cooldown',prescription:`${min} min easy`,type:'time',minutes:min,rest:0,notes:'Pain or symptoms were logged today, so this is a walk. Skip anything that provokes it. If it keeps showing up, get it evaluated by someone qualified. This app does not diagnose.'}; }
// Called by effectiveWorkout(day) in app.js. Returns null when the 15K plan is off so the hunter program runs untouched.
function fitWorkoutFor(day,type){ if(!type&&!fitPlanOn()) return null; const t=type||fitDayType(day), def=fitSessionDef(t), mode=equipmentMode(); const w=JSON.parse(JSON.stringify(def)); w.fit=t; w.mode=mode; w.block=currentBlock(); w.exercises=w.exercises.map(e=>e.type==='strength'?{...substituteExercise(e,mode),sets:e.sets,prescription:e.prescription,notes:e.notes||''}:e); return w; }
function fitSessionTitle(day){ return fitPlanOn()?fitSessionDef(fitDayType(day)).title:null; }
function fitPainToday(){ const r=typeof todayReadiness==='function'?todayReadiness():null; return !!(r&&r.pain); }
function fitStartSession(type){ const w=fitWorkoutFor(dayName(),type); if(!w) return; if(!w.duration){ quickLogRecovery(); return; } Alerts.unlock(); active={day:dayName(),workout:w,index:0,set:1,logs:[],started:Date.now(),historyStack:[],mode:'workout',block:null}; openModal(workoutModal()); clearInterval(workoutTimer); workoutTimer=setInterval(tickTimers,500); }

// ---------- interval timer (hooks from blockSeconds / blockTimerMarkup / tickTimers / completeSet) ----------
function fitIntervalSegments(e){ const segs=[{kind:'walk',label:'WARM-UP WALK',sec:(e.warm||0)*60}]; for(let i=1;i<=(e.reps||0);i++){ segs.push({kind:'jog',label:`JOG · ${i} of ${e.reps}`,sec:e.jog}); segs.push({kind:'walk',label:`WALK · ${i} of ${e.reps}`,sec:e.walk}); } segs.push({kind:'walk',label:'COOL-DOWN WALK',sec:(e.cool||0)*60}); return segs.filter(s=>s.sec>0); }
function fitIntervalTotal(e){ return fitIntervalSegments(e).reduce((a,s)=>a+s.sec,0); }
function fitSegmentAt(e,elapsed){ const segs=fitIntervalSegments(e); let t=0; for(let i=0;i<segs.length;i++){ if(elapsed<t+segs[i].sec) return {i,seg:segs[i],left:Math.ceil(t+segs[i].sec-elapsed),count:segs.length}; t+=segs[i].sec; } const last=segs[segs.length-1]; return {i:segs.length-1,seg:last,left:0,count:segs.length,done:true}; }
function fitIntervalCueMarkup(e){ const b=active&&active.block&&active.block.exIndex===active.index?active.block:null; const elapsed=b?b.total-blockLeft():0; const at=fitSegmentAt(e,elapsed); return `<div class="fit-cue ${at.seg.kind}" id="intervalCue"><div class="fit-cue-label" id="intervalCueLabel">${b?at.seg.label:'READY · press start'}</div><div class="fit-cue-time" id="intervalCueTime">${fmt(b?at.left:at.seg.sec)}</div><div class="note" id="intervalCueNext">${b?fitNextSegLabel(e,at):'Walk warm-up, then the app calls every jog and walk. Ticks at 3-2-1, two beeps at the change.'}</div></div>`; }
function fitNextSegLabel(e,at){ const segs=fitIntervalSegments(e); const n=segs[at.i+1]; return n?`Next: ${n.label.toLowerCase()} · ${fitSecLabel(n.sec)}`:'Last segment. Walk it in.'; }
function fitTickIntervals(){ if(!active||!active.block) return; const e=currentEx(); if(!e||e.type!=='intervals'||active.block.exIndex!==active.index) return; const elapsed=active.block.total-blockLeft(); const at=fitSegmentAt(e,elapsed); const cue=$('#intervalCue'); if(!cue) return; const lab=$('#intervalCueLabel'),tm=$('#intervalCueTime'),nx=$('#intervalCueNext'); if(lab) lab.textContent=at.seg.label; if(tm) tm.textContent=fmt(at.left); if(nx) nx.textContent=fitNextSegLabel(e,at); cue.classList.toggle('jog',at.seg.kind==='jog'); cue.classList.toggle('walk',at.seg.kind!=='jog'); if(active.block.fitSeg!==at.i){ if(active.block.fitSeg!==undefined&&!at.done) Alerts.go(); active.block.fitSeg=at.i; } else if(at.left>0&&at.left<=3&&active.block.fitTick!==at.left){ active.block.fitTick=at.left; Alerts.tick(); } }
function fitIntervalInputs(e){ return `<div class="set-grid"><div class="field"><label>Distance (mi, optional)</label><input id="distanceInput" inputmode="decimal" placeholder="by hand or your watch"></div><div class="field"><label>Longest nonstop jog (min)</label><input id="continuousInput" inputmode="decimal" value="${(e.jog/60).toFixed(1).replace('.0','')}"></div></div><div class="set-grid"><div class="field"><label>Effort 1–10</label><input id="effortInput" inputmode="numeric" placeholder="6 = could talk"></div><div class="field"><label>Rounds done</label><input id="roundsInput" inputmode="numeric" value="${e.reps}"></div></div><label class="check-row"><input type="checkbox" id="painInput"><span>Pain, numbness, weakness, or radiating symptoms during this session</span></label><div class="field"><label>Notes</label><input id="noteInput" placeholder="Optional"></div><p class="note">Press START on the timer above and it runs the whole session. Complete when you are done, even if you stopped early.</p>`; }
function fitCollectLog(log,e){ if($('#effortInput')) log.effort=+$('#effortInput').value||0; if($('#continuousInput')) log.continuous=+$('#continuousInput').value||0; if($('#painInput')) log.pain=$('#painInput').checked; if(e&&e.type==='intervals'){ log.jog=e.jog; log.walk=e.walk; log.repsPlanned=e.reps; log.minutes=log.timedSeconds?Math.round(log.timedSeconds/60):e.minutes; log.step=(fitState()?.run?.step)||1; } }
function fitLogDescription(l){ if(l.type!=='intervals') return null; return `${l.minutes||0} min • ${l.rounds??l.repsPlanned??0} × (${fitSecLabel(l.jog||0)}/${fitSecLabel(l.walk||0)})${l.distance?` • ${l.distance} mi`:''}${l.continuous?` • ${l.continuous} min nonstop`:''}${l.pain?' • PAIN LOGGED':''}`; }
function fitSessionEditorInputs(e,id,first,num){ if(e.type!=='intervals') return null; return `<div class="set-grid three">${num('Minutes','minutes',first.minutes,e.minutes)}${num('Miles','distance',first.distance)}${num('Rounds','rounds',first.rounds,e.reps)}</div>${num('Longest nonstop jog (min)','continuous',first.continuous)}`; }
function fitCollectEditorLog(type,name,n){ if(type!=='intervals') return null; if(!(n('minutes')||n('distance')||n('rounds'))) return false; return {name,set:1,type,minutes:n('minutes'),distance:n('distance'),rounds:n('rounds'),continuous:n('continuous')}; }

// ---------- run plan: progression, race date, taper ----------
function fitRunLogs(days=null){ const since=days?Date.now()-days*864e5:0; const out=[]; getState().history.forEach(h=>{ if(since&&+new Date(h.date)<since) return; (h.logs||[]).forEach(l=>{ if(l.type==='intervals') out.push({...l,date:h.date}); }); }); return out; }
function fitRaceDays(){ const d=fitState()?.profile?.race?.date; return d?daysUntil(d):null; }
function fitTaper(){ const d=fitRaceDays(); return d!==null&&d>=0&&d<=10; }
function fitPainRecent(days=7){ const since=Date.now()-days*864e5; const r=getState().readiness; const painCheck=Object.entries(r).some(([k,v])=>v&&v.pain&&+new Date(k+'T12:00:00')>=since); return painCheck||fitRunLogs(days).some(l=>l.pain); }
function fitReadinessAvg(days=7){ const since=Date.now()-days*864e5; const vals=Object.entries(getState().readiness).filter(([k,v])=>v&&+new Date(k+'T12:00:00')>=since).map(([,v])=>v.score); return vals.length?Math.round(vals.reduce((a,b)=>a+b,0)/vals.length):null; }
function fitProgressionCheck(){ const s=fitState(); if(!s) return {ok:false,reasons:['Plan not set up.']}; const step=s.run.step; if(step>=FIT_RUN_STEPS.length) return {ok:false,top:true,reasons:['Top of the ladder.']}; const atStep=fitRunLogs(null).filter(l=>(l.step||1)===step&&+new Date(l.date)>=+new Date((s.run.stepSince||'2000-01-01')+'T00:00:00')); const reasons=[]; if(atStep.length<3) reasons.push(`${3-atStep.length} more run/walk session${3-atStep.length===1?'':'s'} at this step`); if(fitPainRecent(7)) reasons.push('seven pain-free days (pain was logged this week)'); const ra=fitReadinessAvg(7); if(ra!==null&&ra<55) reasons.push('better recovery (readiness this week averages under 55)'); const hard=atStep.filter(l=>l.effort>=8).length; if(hard>=2) reasons.push('easier sessions (two or more logged at effort 8+)'); return {ok:reasons.length===0,reasons,done:atStep.length}; }
function fitApproveStep(){ const s=fitState(); const c=fitProgressionCheck(); if(!c.ok){ alert('Not yet: '+c.reasons.join('; ')+'.'); return; } if(!confirm(`Move to step ${s.run.step+1}: ${FIT_RUN_STEPS[s.run.step].label}? Jogs get longer, walks stay 2 minutes, pace stays conversational.`)) return; s.run.approvals.push({from:s.run.step,to:s.run.step+1,at:new Date().toISOString()}); s.run.step++; s.run.stepSince=localDateKey(); fitSave(s); renderToday(); }
function fitStepBack(){ const s=fitState(); if(s.run.step<=1) return; if(!confirm('Drop back one step? Smart after a layoff, a cold, or a rough week.')) return; s.run.approvals.push({from:s.run.step,to:s.run.step-1,at:new Date().toISOString()}); s.run.step--; s.run.stepSince=localDateKey(); fitSave(s); renderToday(); }
function fitRaceOutlook(){ const s=fitState(); const d=fitRaceDays(); if(d===null) return null; const weeks=Math.max(0,Math.floor(d/7)); const step=s.run.step; const reachable=Math.min(FIT_RUN_STEPS.length,step+Math.max(0,weeks-2)); const month=new Date(s.profile.race.date+'T00:00:00').getMonth(); const jan=month===0; const top=FIT_RUN_STEPS[reachable-1];
  let line=`${d} days · about ${weeks} weeks. One step a week at most, with the last ten days easy, puts you around step ${reachable} (${top.label.toLowerCase()}) by race day.`;
  if(d<0) line='Race day has passed. Set the next one in Settings → Plan.';
  else if(weeks<10) line+=jan?' A January date is tight from a quarter-mile base: expect to run/walk the whole 9.3 miles, and finishing that way is the goal, not a consolation.':' That is a short runway: plan on run/walk the whole way and treat finishing as the win.';
  else line+=' Enough runway to build patiently. The long day grows a little each step; nothing jumps.';
  if(s.profile.race.mode==='continuous') line+=' Your stated aim is a continuous run. The app will not promise that; it will show you the longest nonstop jog you have actually done.';
  return {days:d,weeks,reachable,line}; }

// ---------- weight ----------
function fitWeekAvgs(n=8){ const by={}; getState().bodyHistory.filter(x=>x.weight).forEach(x=>{ const k=campWeekKey(x.date); (by[k]??=[]).push(Number(x.weight)); }); return Object.keys(by).sort().slice(-n).map(k=>({week:k,date:k,avg:Math.round(by[k].reduce((a,b)=>a+b,0)/by[k].length*10)/10,n:by[k].length})); }
function fitWeightTrend(){ const w=fitWeekAvgs(10); const last=w.at(-1),prev=w.at(-2); const rate=last&&prev?Math.round((last.avg-prev.avg)*10)/10:null; let fast=0; for(let i=w.length-1;i>0;i--){ if(w[i-1].avg-w[i].avg>1.5) fast++; else break; } return {weeks:w,last,prev,rate,fastWeeks:fast}; }
function fitQuickWeight(){ const v=Number($('#fitWeightInput')?.value||0); if(!v){ alert('Enter a weight.'); return; } const h=getState().bodyHistory; const today=localDateKey(); const i=h.findIndex(x=>localDateKey(new Date(x.date))===today); if(i>=0){ h[i].weight=v; h[i].date=new Date().toISOString(); } else h.unshift({date:new Date().toISOString(),weight:v,waist:0}); STORE.set('hr30_bodyHistory',h.slice(0,365)); fitCheckMilestones(); renderToday(); }
function fitWeightCard(){ const s=fitState(), p=s.profile, t=fitWeightTrend(), latest=getState().bodyHistory.find(x=>x.weight); const todayKey=localDateKey(); const loggedToday=latest&&localDateKey(new Date(latest.date))===todayKey;
  const trend=t.rate===null?'Two weeks of weigh-ins and the weekly trend shows here.':`${t.rate>0?'+':''}${t.rate} lb vs last week's average${Math.abs(t.rate)<=1.5?(t.rate<=0?' · inside the 1–1.5 lb/week guideline':''):t.rate<0?' · faster than the guideline':''}.`;
  const flag=t.fastWeeks>=2?`<div class="notice" style="margin-top:10px"><strong>Review fueling and recovery.</strong> Weight has dropped more than 1.5 lb a week for ${t.fastWeeks} weeks running. Eat to the target, keep protein up, check sleep. The app changes nothing on its own.</div>`:'';
  const toGo=latest&&p.goalWeight?Math.round((latest.weight-p.goalWeight)*10)/10:null;
  return `<section class="card"><div class="section-title" style="margin:0 0 6px"><h3>Weight</h3><small>${latest?`${latest.weight} lb${loggedToday?' · today':' · '+new Date(latest.date).toLocaleDateString()}`:'no weigh-ins yet'}</small></div><p class="note" style="margin:0 0 8px">${trend}${toGo!==null?` ${toGo>0?`${toGo} lb to ${p.goalWeight}.`:'At goal. Hold it and keep the strength.'}`:''} Weekly averages, not daily swings. The guideline is 1–1.5 lb a week, not a daily quota.</p><div class="fit-inline"><input id="fitWeightInput" inputmode="decimal" placeholder="${latest?latest.weight:'lb'}" aria-label="Today's weight in pounds"><button class="secondary" onclick="fitQuickWeight()">${loggedToday?'UPDATE':'LOG WEIGHT'}</button></div>${flag}</section>`; }

// ---------- fuel: slots, saved meals, protein, hydration ----------
function fitTodayMeals(){ const today=localDateKey(); return getState().meals.filter(m=>m.dateKey===today); }
function fitProteinToday(){ return fitTodayMeals().reduce((a,m)=>a+Number(m.protein||0),0); }
function fitSlotLogged(key){ return fitTodayMeals().filter(m=>m.slot===key); }
function fitQuickLog(slotKey,mealId){ const s=fitState(); const slot=s.mealSlots.find(x=>x.key===slotKey); const saved=mealId?s.savedMeals.find(m=>m.id===mealId):s.savedMeals.find(m=>m.slot===slotKey); const m=saved||{name:slot?slot.label:'Meal',protein:0,calories:0,carbs:0,fat:0,portion:''};
  openModal(`<div class="close-row"><div><div class="kicker">${esc(slot?slot.label.toUpperCase():'MEAL')} · ${slot?slot.time:''}</div><h2>Log it</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div>
  <div class="field"><label>Saved meal</label><select id="fitQlMeal" onchange="fitQuickLog('${slotKey}',this.value)"><option value="">Custom</option>${s.savedMeals.map(x=>`<option value="${x.id}" ${saved&&saved.id===x.id?'selected':''}>${esc(x.name)} · ${x.protein||'?'} g P</option>`).join('')}</select></div>
  <div class="field"><label>Name</label><input id="fitQlName" value="${esc(m.name)}"></div>
  ${m.portion?`<p class="note" style="margin:-4px 0 10px">${esc(m.portion)}</p>`:''}
  <div class="set-grid"><div class="field"><label>Protein (g) · from the label</label><input id="fitQlProtein" inputmode="decimal" value="${m.protein||''}" placeholder="${/shake/i.test(m.name)?'grams per your scoop':''}"></div><div class="field"><label>Portion × (1 = as saved)</label><input id="fitQlMult" inputmode="decimal" value="1"></div></div>
  <div class="set-grid"><div class="field"><label>Calories (optional)</label><input id="fitQlCal" inputmode="decimal" value="${m.calories||''}"></div><div class="field"><label>Carbs (g)</label><input id="fitQlCarb" inputmode="decimal" value="${m.carbs||''}"></div><div class="field"><label>Fat (g)</label><input id="fitQlFat" inputmode="decimal" value="${m.fat||''}"></div></div>
  ${/shake/i.test(m.name)&&!m.protein?'<div class="notice">Protein per scoop comes off your powder\'s label. The app will not guess a scoop size. Enter it once and tick "remember" below.</div>':''}
  <label class="check-row"><input type="checkbox" id="fitQlRemember" ${saved?'checked':''}><span>Remember these numbers for this saved meal</span></label>
  <button class="primary" onclick="fitSaveQuickLog('${slotKey}','${saved?saved.id:''}')">LOG ${esc((slot?slot.label:'meal').toUpperCase())}</button>`); }
function fitSaveQuickLog(slotKey,savedId){ const s=fitState(); const mult=Number($('#fitQlMult').value)||1; const base={name:$('#fitQlName').value.trim()||'Meal',protein:+$('#fitQlProtein').value||0,calories:+$('#fitQlCal').value||0,carbs:+$('#fitQlCarb').value||0,fat:+$('#fitQlFat').value||0}; if(!base.protein&&!base.calories){ if(!confirm('No protein or calories entered. Log it anyway?')) return; }
  if($('#fitQlRemember').checked){ const sm=savedId?s.savedMeals.find(m=>m.id===savedId):null; if(sm) Object.assign(sm,base); else s.savedMeals.push({id:uid(),slot:slotKey,portion:'',...base}); fitSave(s); }
  const meals=getState().meals; meals.unshift({id:uid(),dateKey:localDateKey(),createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),slot:slotKey,name:base.name,calories:Math.round(base.calories*mult),protein:Math.round(base.protein*mult),carbs:Math.round(base.carbs*mult),fat:Math.round(base.fat*mult),fiber:0,notes:mult!==1?`${mult}× portion`:''}); STORE.set('hr30_meals',meals.slice(0,500)); closeModal(); fitCheckMilestones(); if(currentTab==='fuel') renderFuel(); else renderToday(); }
function fitSlotsMarkup(compact=false){ const s=fitState(); const now=new Date(); const hm=now.getHours()*60+now.getMinutes();
  return `<div class="fit-slots">${s.mealSlots.map(sl=>{ const logged=fitSlotLogged(sl.key); const [h,m]=sl.time.split(':').map(Number); const due=hm>=h*60+m; const p=logged.reduce((a,x)=>a+Number(x.protein||0),0); return `<button class="fit-slot ${logged.length?'done':due?'due':''}" onclick="fitQuickLog('${sl.key}')" aria-label="${esc(sl.label)} at ${sl.time}${logged.length?', logged':''}"><span class="fit-slot-time">${fitClock(sl.time)}</span><strong>${esc(sl.label)}</strong><small>${logged.length?`${p} g P ✓`:due?'Not logged':'Later'}</small></button>`; }).join('')}</div>`; }
function fitClock(t){ const [h,m]=t.split(':').map(Number); const ap=h>=12?'PM':'AM'; return `${((h+11)%12)+1}:${String(m).padStart(2,'0')} ${ap}`; }
function fitHydrationToday(){ const s=fitState(); return (s.hydrationLog[localDateKey()]||[]); }
function fitAddHydration(product,servings=1){ const s=fitState(); const k=localDateKey(); (s.hydrationLog[k]??=[]).push({id:uid(),product,servings,at:new Date().toISOString()}); const keys=Object.keys(s.hydrationLog).sort(); if(keys.length>120) keys.slice(0,keys.length-120).forEach(x=>delete s.hydrationLog[x]); fitSave(s); if(currentTab==='fuel') renderFuel(); else renderToday(); }
function fitUndoHydration(){ const s=fitState(); const arr=s.hydrationLog[localDateKey()]||[]; arr.pop(); fitSave(s); if(currentTab==='fuel') renderFuel(); else renderToday(); }
function fitHydrationMarkup(){ const s=fitState(); const log=fitHydrationToday(); const tot=log.reduce((a,x)=>a+Number(x.servings||0),0); const pct=Math.min(100,Math.round(tot/(s.hydration.target||1)*100)); const lytes=log.reduce((a,x)=>{ const p=s.hydration.products.find(q=>q.name===x.product); if(p){ a.sodium+=(Number(p.sodium)||0)*x.servings; a.potassium+=(Number(p.potassium)||0)*x.servings; a.magnesium+=(Number(p.magnesium)||0)*x.servings; } return a; },{sodium:0,potassium:0,magnesium:0});
  return `<div class="fit-hydra"><div class="row" style="display:flex;justify-content:space-between;align-items:baseline"><strong>${tot} / ${s.hydration.target} servings</strong><small class="note">${lytes.sodium?`${lytes.sodium} mg sodium`:'label values not set'}${lytes.potassium?` · ${lytes.potassium} mg K`:''}${lytes.magnesium?` · ${lytes.magnesium} mg Mg`:''}</small></div><div class="progress-bar"><span style="width:${pct}%"></span></div><div class="fit-chips">${s.hydration.products.map(p=>`<button class="secondary fit-chip" onclick="fitAddHydration('${esc(p.name)}')">+ ${esc(p.name)}</button>`).join('')}${log.length?`<button class="ghost" onclick="fitUndoHydration()">Undo</button>`:''}</div><p class="note" style="margin:6px 0 0">A serving is whatever you drink from: a bottle, a glass, a packet. Electrolyte numbers come only from your own labels (Fuel → Hydration products). No universal dose.</p></div>`; }
function fitFuelCard(){ const t=getState().nutritionTargets; const p=fitProteinToday(); const pct=t.protein?Math.min(100,Math.round(p/t.protein*100)):0;
  return `<section class="card"><div class="section-title" style="margin:0 0 8px"><h3>Fuel today</h3><button class="ghost" onclick="tab('fuel')">Fuel tab →</button></div><div class="row" style="display:flex;justify-content:space-between;align-items:baseline"><strong style="font:700 22px/1 var(--f-head)">${p} g <span style="color:var(--muted);font-size:14px">/ ${t.protein||'—'} g protein</span></strong><small class="note">${t.protein&&p>=t.protein?'Target hit':t.protein?`${t.protein-p} g to go`:'Set a target in Settings'}</small></div><div class="progress-bar"><span style="width:${pct}%"></span></div>${fitSlotsMarkup(true)}<div class="divider" style="margin:12px 0"></div><div class="kicker" style="margin-bottom:6px">Hydration</div>${fitHydrationMarkup()}</section>`; }

// ---------- supplements and medications (user-reported) ----------
function fitSuppActiveToday(x){ if(x.kind==='investigational') return false; if(x.excluded||x.status==='excluded'||x.status==='stopped') return false; if(x.kind==='medication'&&!x.confirmed) return false; if(!['planned','owned','current','user_reported','taking'].includes(x.status)) return false; const sched=(x.schedule||'daily').toLowerCase(); if(sched==='daily'||sched==='') return true; const d=dayName().slice(0,3).toLowerCase(); return sched.split(/[\/,\s]+/).some(p=>p.slice(0,3)===d); }
function fitToggleSupp(id){ const s=fitState(); const x=s.supps.find(q=>q.id===id); if(!x) return; const k=localDateKey(); x.taken=x.taken||{}; if(x.taken[k]) delete x.taken[k]; else x.taken[k]=new Date().toISOString(); const keys=Object.keys(x.taken).sort(); if(keys.length>400) keys.slice(0,keys.length-400).forEach(q=>delete x.taken[q]); fitSave(s); if(currentTab==='fuel') renderFuel(); else renderToday(); }
function fitSuppsTodayCard(){ const s=fitState(); const list=s.supps.filter(fitSuppActiveToday); const k=localDateKey(); if(!list.length) return `<section class="card"><div class="section-title" style="margin:0 0 6px"><h3>Supplements</h3><button class="ghost" onclick="tab('fuel');setTimeout(()=>document.getElementById('fitSupps')?.scrollIntoView({behavior:'smooth'}),150)">Set up →</button></div><p class="note" style="margin:0">Nothing is on today's list. Mark an item "Taking" on the Fuel tab and it shows here. Medications appear only after you confirm your prescriber's regimen.</p></section>`;
  return `<section class="card"><div class="section-title" style="margin:0 0 6px"><h3>Supplements today</h3><small>user-reported · ${list.filter(x=>x.taken&&x.taken[k]).length} of ${list.length}</small></div>${list.map(x=>`<label class="check-row"><input type="checkbox" ${x.taken&&x.taken[k]?'checked':''} onchange="fitToggleSupp('${x.id}')"><span><strong>${esc(x.name)}</strong>${x.dose?` · ${esc(String(x.dose))} ${esc(x.unit||'')}`:' · dose not set'}${x.kind==='medication'?` · ${esc(x.schedule||'')}`:''}</span></label>`).join('')}<p class="note" style="margin:8px 0 0">What you take is between you and your prescriber. This list only records it.</p></section>`; }
function fitTrtMath(x){ const c=Number(x.concentration)||0, lo=Number(x.weeklyMlMin)||0, hi=Number(x.weeklyMlMax)||0; if(!c||!lo) return ''; const n=(x.schedule||'').split(/[\/,\s]+/).filter(Boolean).length||1; const f=v=>Math.round(v*10)/10; return `${c} mg/mL × ${lo}${hi&&hi!==lo?`–${hi}`:''} mL/week = ${f(c*lo)}${hi&&hi!==lo?`–${f(c*hi)}`:''} mg/week${n>1?` · split ${n} ways ≈ ${(lo/n).toFixed(3)}${hi&&hi!==lo?`–${(hi/n).toFixed(3)}`:''} mL (${f(c*lo/n)}${hi&&hi!==lo?`–${f(c*hi/n)}`:''} mg) each`:''}. Arithmetic on what you reported, not a dose.`; }
function fitSuppsMarkup(){ const s=fitState(); const kinds=[['supplement','Supplements'],['medication','Medications · user-reported'],['investigational','Investigational · not approved · nothing stored']];
  return `<section class="card" id="fitSupps"><div class="section-title" style="margin:0 0 6px"><h3>Supplements &amp; medications</h3><button class="ghost" onclick="fitEditSupp('')">+ Add</button></div><div class="notice" style="margin-bottom:10px">Everything here is what <em>you</em> report. The app does not endorse, dose, titrate, or combine anything. Talk with your prescriber before you start, stop, or change a medication. Health data stays on this phone unless you export it.</div>
  ${kinds.map(([kind,label])=>{ const items=s.supps.filter(x=>x.kind===kind); if(!items.length) return ''; return `<div class="kicker" style="margin:12px 0 4px">${label}</div>${items.map(x=>`<div class="weight-row"><div><strong>${esc(x.name)}</strong><small>${FIT_SUPP_STATUS[x.status]||esc(x.status||'')}${x.kind!=='investigational'?(x.dose?` · ${esc(String(x.dose))} ${esc(x.unit||'')}`:' · dose not set'):''}${x.kind==='medication'?(x.confirmed?' · regimen confirmed by you':' · not confirmed, reminders off'):''}${x.schedule&&x.kind!=='investigational'?` · ${esc(x.schedule)}`:''}${x.kind==='medication'&&fitTrtMath(x)?`<br>${esc(fitTrtMath(x))}`:''}${x.note?`<br>${esc(x.note)}`:''}</small></div><button class="ghost" onclick="fitEditSupp('${x.id}')">Edit</button></div>`).join('')}`; }).join('')}</section>`; }
function fitEditSupp(id){ const s=fitState(); const x=s.supps.find(q=>q.id===id)||{id:'',name:'',kind:'supplement',status:'planned',dose:'',unit:'',schedule:'daily',note:'',confirmed:false}; const inv=x.kind==='investigational';
  openModal(`<div class="close-row"><div><div class="kicker">${id?'EDIT':'ADD'} ITEM</div><h2>${esc(x.name||'New item')}</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div>
  <div class="field"><label>Name</label><input id="fsName" value="${esc(x.name)}"></div>
  <div class="set-grid"><div class="field"><label>Type</label><select id="fsKind" onchange="$('#fsDoseWrap').style.display=this.value==='investigational'?'none':''"><option value="supplement" ${x.kind==='supplement'?'selected':''}>Supplement</option><option value="medication" ${x.kind==='medication'?'selected':''}>Prescribed medication</option><option value="investigational" ${inv?'selected':''}>Investigational / research compound</option></select></div><div class="field"><label>Status</label><select id="fsStatus">${Object.entries(FIT_SUPP_STATUS).map(([k,v])=>`<option value="${k}" ${x.status===k?'selected':''}>${v}</option>`).join('')}</select></div></div>
  <div id="fsDoseWrap" style="${inv?'display:none':''}"><div class="set-grid three"><div class="field"><label>Dose (from label or Rx)</label><input id="fsDose" value="${esc(String(x.dose||''))}" placeholder="leave blank if unknown"></div><div class="field"><label>Unit</label><input id="fsUnit" value="${esc(x.unit||'')}" placeholder="mg, g, IU, mL"></div><div class="field"><label>Schedule</label><input id="fsSched" value="${esc(x.schedule||'daily')}" placeholder="daily or Mon/Wed/Fri"></div></div>
  ${x.kind==='medication'||!id?`<div class="set-grid three" id="fsRxWrap" style="${x.kind==='medication'?'':'display:none'}"><div class="field"><label>Concentration (mg/mL)</label><input id="fsConc" inputmode="decimal" value="${x.concentration||''}"></div><div class="field"><label>Weekly mL (low)</label><input id="fsMlLo" inputmode="decimal" value="${x.weeklyMlMin||''}"></div><div class="field"><label>Weekly mL (high)</label><input id="fsMlHi" inputmode="decimal" value="${x.weeklyMlMax||''}"></div></div><label class="check-row"><input type="checkbox" id="fsConfirm" ${x.confirmed?'checked':''}><span><strong>I confirm this is my current prescriber-directed regimen.</strong> Only then does it appear on the daily checklist. The app never suggests titration.</span></label>`:''}</div>
  ${inv?'<div class="notice">Investigational items keep a name, a status, and a note. No dose, no schedule, no sourcing. If you pursue one, do it under a clinician or an authorized trial.</div>':''}
  <div class="field"><label>Note (lab result, prescriber instruction, label details)</label><textarea id="fsNote" rows="3">${esc(x.note||'')}</textarea></div>
  <button class="primary" onclick="fitSaveSupp('${id}')">SAVE</button>${id?`<button class="ghost danger" style="width:100%;margin-top:10px;text-align:center" onclick="fitDeleteSupp('${id}')">Delete this item</button>`:''}`);
  const k=$('#fsKind'); if(k) k.addEventListener('change',()=>{ const w=$('#fsRxWrap'); if(w) w.style.display=k.value==='medication'?'':'none'; }); }
function fitSaveSupp(id){ const s=fitState(); const x=s.supps.find(q=>q.id===id)||{id:uid(),taken:{}}; x.name=$('#fsName').value.trim()||'Item'; x.kind=$('#fsKind').value; x.status=$('#fsStatus').value; x.note=$('#fsNote').value.trim(); if(x.kind==='investigational'){ x.dose=''; x.unit=''; x.schedule=''; x.confirmed=false; delete x.concentration; delete x.weeklyMlMin; delete x.weeklyMlMax; } else { x.dose=$('#fsDose').value.trim(); x.unit=$('#fsUnit').value.trim(); x.schedule=$('#fsSched').value.trim()||'daily'; if(x.kind==='medication'){ x.confirmed=!!$('#fsConfirm')?.checked; x.concentration=+($('#fsConc')?.value||0)||undefined; x.weeklyMlMin=+($('#fsMlLo')?.value||0)||undefined; x.weeklyMlMax=+($('#fsMlHi')?.value||0)||undefined; } else x.confirmed=false; } if(!id) s.supps.push(x); fitSave(s); closeModal(); renderFuel(); }
function fitDeleteSupp(id){ if(!confirm('Delete this item and its taken-history?')) return; const s=fitState(); s.supps=s.supps.filter(q=>q.id!==id); fitSave(s); closeModal(); renderFuel(); }

// ---------- saved meals, meal prep, grocery ----------
function fitSavedMealsMarkup(){ const s=fitState(); return `<section class="card"><div class="section-title" style="margin:0 0 6px"><h3>Saved meals</h3><button class="ghost" onclick="fitEditSavedMeal('')">+ Add</button></div><p class="note" style="margin:0 0 8px">Reusable plates and shakes. Tap a slot on Today to log one in two taps. Protein comes from the label or the scale, never a guess.</p>${s.savedMeals.map(m=>`<div class="weight-row"><div><strong>${esc(m.name)}</strong><small>${esc(s.mealSlots.find(x=>x.key===m.slot)?.label||'any slot')} · ${m.protein||'?'} g P${m.calories?` · ${m.calories} kcal`:''}${m.portion?`<br>${esc(m.portion)}`:''}</small></div><div style="display:flex;gap:8px"><button class="ghost" onclick="fitQuickLog('${m.slot}','${m.id}')">Log</button><button class="ghost" onclick="fitEditSavedMeal('${m.id}')">Edit</button></div></div>`).join('')||'<div class="empty">No saved meals yet.</div>'}</section>`; }
function fitEditSavedMeal(id){ const s=fitState(); const m=s.savedMeals.find(x=>x.id===id)||{id:'',name:'',slot:'lunch',protein:'',calories:'',carbs:'',fat:'',portion:''}; openModal(`<div class="close-row"><div><div class="kicker">${id?'EDIT':'NEW'} SAVED MEAL</div><h2>${esc(m.name||'Meal')}</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="field"><label>Name</label><input id="smName" value="${esc(m.name)}"></div><div class="field"><label>Default slot</label><select id="smSlot">${s.mealSlots.map(x=>`<option value="${x.key}" ${m.slot===x.key?'selected':''}>${esc(x.label)} · ${fitClock(x.time)}</option>`).join('')}</select></div><div class="set-grid"><div class="field"><label>Protein (g)</label><input id="smP" inputmode="decimal" value="${m.protein||''}"></div><div class="field"><label>Calories</label><input id="smC" inputmode="decimal" value="${m.calories||''}"></div></div><div class="set-grid"><div class="field"><label>Carbs (g)</label><input id="smCb" inputmode="decimal" value="${m.carbs||''}"></div><div class="field"><label>Fat (g)</label><input id="smF" inputmode="decimal" value="${m.fat||''}"></div></div><div class="field"><label>Portion notes</label><input id="smPortion" value="${esc(m.portion||'')}" placeholder="e.g. 175 g sweet potato · 125 g green beans · 6 oz chicken"></div><button class="primary" onclick="fitSaveSavedMeal('${id}')">SAVE</button>${id?`<button class="ghost danger" style="width:100%;margin-top:10px;text-align:center" onclick="fitDeleteSavedMeal('${id}')">Delete</button>`:''}`); }
function fitSaveSavedMeal(id){ const s=fitState(); const m=s.savedMeals.find(x=>x.id===id)||{id:uid()}; m.name=$('#smName').value.trim()||'Meal'; m.slot=$('#smSlot').value; m.protein=+$('#smP').value||0; m.calories=+$('#smC').value||0; m.carbs=+$('#smCb').value||0; m.fat=+$('#smF').value||0; m.portion=$('#smPortion').value.trim(); if(!id) s.savedMeals.push(m); fitSave(s); closeModal(); renderFuel(); }
function fitDeleteSavedMeal(id){ if(!confirm('Delete this saved meal?')) return; const s=fitState(); s.savedMeals=s.savedMeals.filter(x=>x.id!==id); fitSave(s); closeModal(); renderFuel(); }
function fitPrepMarkup(){ const s=fitState(); const p=s.prep; const sp=p.mainMeals*p.sweetPotatoPerMealG, gb=p.mainMeals*p.greenBeansPerMealG; const items=p.items&&p.items.length?p.items:null;
  return `<section class="card"><div class="section-title" style="margin:0 0 6px"><h3>3-day meal prep</h3><small>${p.resetAt?`list from ${new Date(p.resetAt).toLocaleDateString()}`:'grocery + batch'}</small></div><div class="set-grid three"><div class="field"><label>Main meals</label><input id="fpMeals" inputmode="numeric" value="${p.mainMeals}"></div><div class="field"><label>Sweet potato g / meal</label><input id="fpSp" inputmode="numeric" value="${p.sweetPotatoPerMealG}"></div><div class="field"><label>Green beans g / meal</label><input id="fpGb" inputmode="numeric" value="${p.greenBeansPerMealG}"></div></div><button class="secondary" style="width:100%" onclick="fitSavePrep()">UPDATE QUANTITIES</button><p class="note" style="margin:10px 0 4px"><strong>Batch:</strong> ${sp} g plain frozen cut sweet potato (not the oily fries) · ${gb} g green beans · protein portions sized to hit ${getState().nutritionTargets.protein||190} g a day across the four feedings.</p><div class="kicker" style="margin:12px 0 4px">Grocery list</div>${items?items.map(it=>`<label class="check-row"><input type="checkbox" ${it.done?'checked':''} onchange="fitToggleGrocery('${it.id}')"><span>${esc(it.label)}</span></label>`).join(''):`<p class="note">Build the list from your preferred foods (edit them in Settings → Plan).</p>`}<div style="display:flex;gap:10px;margin-top:10px"><button class="secondary" style="margin:0;flex:1" onclick="fitResetGrocery()">${items?'NEW LIST':'BUILD LIST'}</button>${items?`<button class="ghost" onclick="fitAddGrocery()">+ Item</button>`:''}</div><p class="note" style="margin:8px 0 0">Stores: ${esc(s.stores.join(', '))}.</p></section>`; }
function fitSavePrep(){ const s=fitState(); s.prep.mainMeals=+$('#fpMeals').value||6; s.prep.sweetPotatoPerMealG=+$('#fpSp').value||175; s.prep.greenBeansPerMealG=+$('#fpGb').value||125; fitSave(s); renderFuel(); }
function fitResetGrocery(){ const s=fitState(); const p=s.prep; const sp=p.mainMeals*p.sweetPotatoPerMealG, gb=p.mainMeals*p.greenBeansPerMealG; const base=[`Plain frozen cut sweet potatoes · ${sp} g (${(sp/454).toFixed(1)} lb)`,`Green beans · ${gb} g (${(gb/454).toFixed(1)} lb)`,'Protein powder · check the tub','Eggs · 1–2 dozen']; const foods=s.foods.filter(f=>!/sweet potato|green beans|eggs|ravioli/i.test(f)); s.prep.items=[...base,...foods.map(f=>f.charAt(0).toUpperCase()+f.slice(1))].map(label=>({id:uid(),label,done:false})); s.prep.resetAt=new Date().toISOString(); fitSave(s); renderFuel(); }
function fitToggleGrocery(id){ const s=fitState(); const it=(s.prep.items||[]).find(x=>x.id===id); if(it){ it.done=!it.done; fitSave(s); } }
function fitAddGrocery(){ const label=prompt('Add to the grocery list:'); if(!label) return; const s=fitState(); (s.prep.items??=[]).push({id:uid(),label:label.trim(),done:false}); fitSave(s); renderFuel(); }
function fitHydrationProductsMarkup(){ const s=fitState(); return `<section class="card"><div class="section-title" style="margin:0 0 6px"><h3>Hydration</h3><small>target ${s.hydration.target} servings</small></div>${fitHydrationMarkup()}<div class="kicker" style="margin:12px 0 4px">Products · label values per serving</div>${s.hydration.products.map((p,i)=>`<div class="weight-row"><div><strong>${esc(p.name)}</strong><small>${p.sodium!=null&&p.sodium!==''?`${p.sodium} mg Na`:'Na ?'} · ${p.potassium!=null&&p.potassium!==''?`${p.potassium} mg K`:'K ?'} · ${p.magnesium!=null&&p.magnesium!==''?`${p.magnesium} mg Mg`:'Mg ?'}${p.note?`<br>${esc(p.note)}`:''}</small></div><button class="ghost" onclick="fitEditProduct(${i})">Edit</button></div>`).join('')}<button class="ghost" onclick="fitEditProduct(-1)">+ Add product</button><p class="note" style="margin:8px 0 0">Log a packet once, under its own name, so sodium is never counted twice.</p></section>`; }
function fitEditProduct(i){ const s=fitState(); const p=i>=0?s.hydration.products[i]:{name:'',sodium:'',potassium:'',magnesium:'',note:''}; openModal(`<div class="close-row"><div><div class="kicker">HYDRATION PRODUCT</div><h2>${esc(p.name||'New')}</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="field"><label>Name</label><input id="hpName" value="${esc(p.name)}"></div><div class="set-grid three"><div class="field"><label>Sodium mg</label><input id="hpNa" inputmode="decimal" value="${p.sodium??''}"></div><div class="field"><label>Potassium mg</label><input id="hpK" inputmode="decimal" value="${p.potassium??''}"></div><div class="field"><label>Magnesium mg</label><input id="hpMg" inputmode="decimal" value="${p.magnesium??''}"></div></div><div class="field"><label>Note</label><input id="hpNote" value="${esc(p.note||'')}"></div><button class="primary" onclick="fitSaveProduct(${i})">SAVE</button>${i>0?`<button class="ghost danger" style="width:100%;margin-top:10px;text-align:center" onclick="fitDeleteProduct(${i})">Delete</button>`:''}`); }
function fitSaveProduct(i){ const s=fitState(); const p={name:$('#hpName').value.trim()||'Drink',sodium:$('#hpNa').value===''?null:+$('#hpNa').value,potassium:$('#hpK').value===''?null:+$('#hpK').value,magnesium:$('#hpMg').value===''?null:+$('#hpMg').value,note:$('#hpNote').value.trim()}; if(i>=0) s.hydration.products[i]=p; else s.hydration.products.push(p); fitSave(s); closeModal(); renderFuel(); }
function fitDeleteProduct(i){ const s=fitState(); s.hydration.products.splice(i,1); fitSave(s); closeModal(); renderFuel(); }
function fitFuelMarkup(){ return `<section class="card"><div class="section-title" style="margin:0 0 8px"><h3>Today's plan</h3><small>no breakfast · four feedings</small></div>${fitSlotsMarkup()}<p class="note" style="margin:8px 0 0">Aim for 40–55 g of protein per feeding. Times are yours to move in Settings → Plan.</p></section>${fitSavedMealsMarkup()}${fitHydrationProductsMarkup()}${fitPrepMarkup()}${fitSuppsMarkup()}`; }

// ---------- Today cards ----------
function fitRunCard(){ const s=fitState(); const on=fitPlanOn(); const step=s.run.step; const st=FIT_RUN_STEPS[step-1]; const chk=fitProgressionCheck(); const out=fitRaceOutlook(); const longest=Math.max(0,...fitRunLogs(null).map(l=>Number(l.continuous)||0)); const wk=fitRunLogs(7);
  const head=out?`<div class="kicker"><span class="led"></span>15K · ${out.days} days</div>`:`<div class="kicker">15K · ${esc(s.profile.race.window||'date not set')}</div>`;
  const body=on?`<p class="sub" style="margin:4px 0 0">Step ${step} of ${FIT_RUN_STEPS.length} · ${st.label}</p><p class="note" style="margin:6px 0 0">This week: ${wk.length} run/walk session${wk.length===1?'':'s'} · ${wk.reduce((a,l)=>a+(Number(l.minutes)||0),0)} min · ${Math.round(wk.reduce((a,l)=>a+(Number(l.distance)||0),0)*10)/10} mi${longest?` · longest nonstop jog ${longest} min`:''}</p>${out?`<p class="note" style="margin:6px 0 0">${esc(out.line)}</p>`:`<p class="note" style="margin:6px 0 0">Pick the race date in Settings → Plan and the app lays out the runway. Until then, step 1 is the whole job.</p>`}
    ${chk.top?'':chk.ok?`<div class="notice" style="margin-top:10px"><strong>Ready for step ${step+1}.</strong> Three sessions in, no pain this week, recovery holding. Your call.<button class="primary" style="width:100%;margin-top:8px" onclick="fitApproveStep()">APPROVE STEP ${step+1} · ${FIT_RUN_STEPS[step].label.toUpperCase()}</button></div>`:`<p class="note" style="margin:6px 0 0">Next step opens after: ${chk.reasons.join('; ')}. The app never bumps you on its own.</p>`}
    <div style="display:flex;gap:16px;flex-wrap:wrap;margin-top:10px"><button class="ghost" onclick="fitStartSession('run_walk')">Run / walk now →</button>${step>1?`<button class="ghost" onclick="fitStepBack()">Step back</button>`:''}<button class="ghost" onclick="openSettings()">Plan settings</button></div>`
  :`<p class="sub" style="margin:4px 0 0">The 15K plan is off. The hunter program runs as before.</p><p class="note" style="margin:6px 0 0">Turn it on in Settings → Plan: three run/walk days, Strength A and B, a recovery day, and optional hunt conditioning, starting from a quarter-mile base. Or run a single session now.</p><div style="display:flex;gap:16px;flex-wrap:wrap;margin-top:10px"><button class="ghost" onclick="fitStartSession('run_walk')">Run / walk session →</button><button class="ghost" onclick="openSettings()">Turn on the plan</button></div>`;
  return `<section class="card">${head}${body}</section>`; }
function fitTodayCards(){ if(!fitState()) return ''; return fitFuelCard()+fitWeightCard()+fitSuppsTodayCard()+fitRunCard(); }
function fitOptionalRow(w){ if(!w||!w.optional) return ''; return `<button class="secondary" style="width:100%;margin-top:8px" onclick="quickLogRecovery()">REST INSTEAD · LOG RECOVERY</button>`; }

// ---------- readiness additions ----------
function fitReadinessExtra(){ return `<div class="set-grid" style="margin-top:10px"><div class="field"><label>Hours slept (optional)</label><input id="sleepHours" inputmode="decimal" placeholder="e.g. 6.5"></div></div><label class="check-row"><input type="checkbox" id="painFlag"><span>Pain, numbness, weakness, or symptoms radiating down an arm or leg this morning</span></label>`; }
function fitReadinessRead(r){ const h=$('#sleepHours'); if(h&&h.value) r.sleepHours=+h.value; const p=$('#painFlag'); if(p) r.pain=p.checked; }
function fitPainBanner(r){ if(!r||!r.pain) return ''; return `<div class="notice" style="margin-top:10px"><strong>Symptoms logged.</strong> Skip whatever provokes it today, keep the session easy, and if it shows up again this week get it looked at by someone qualified. Numbness, weakness, or pain shooting down a limb is not something to train through. The app trims today and does not diagnose.</div>`; }

// ---------- progress / insights ----------
function fitMilestoneDefs(){ return [
  {key:'first_runwalk',label:'First run/walk session logged',test:()=>fitRunLogs(null).length>=1},
  {key:'runwalk30',label:'First 30-minute run/walk',test:()=>fitRunLogs(null).some(l=>Number(l.minutes)>=30)},
  {key:'three_week',label:'Three sessions in one week',test:()=>{ const by={}; getState().history.forEach(h=>{ const k=campWeekKey(h.date); by[k]=(by[k]||0)+1; }); return Object.values(by).some(n=>n>=3); }},
  {key:'nonstop5',label:'Five minutes nonstop',test:()=>fitRunLogs(null).some(l=>Number(l.continuous)>=5)},
  {key:'nonstop10',label:'Ten minutes nonstop',test:()=>fitRunLogs(null).some(l=>Number(l.continuous)>=10)},
  {key:'hike45',label:'45-minute comfortable walk or hike',test:()=>getState().history.some(h=>(h.logs||[]).some(l=>(l.type==='ruck'||l.type==='time')&&Number(l.minutes||l.timedSeconds/60)>=45))},
  {key:'hike60',label:'60-minute comfortable walk or hike',test:()=>getState().history.some(h=>(h.logs||[]).some(l=>(l.type==='ruck'||l.type==='time')&&Number(l.minutes||l.timedSeconds/60)>=60))},
  {key:'protein7',label:'Protein target hit 7 days in a row',test:()=>fitProteinStreak()>=7},
  {key:'bow_consistent',label:'Four pain-free bow sessions in a month',test:()=>{ const since=Date.now()-28*864e5; return getState().archery.filter(a=>+new Date(a.date||a.createdAt||0)>=since&&!(Number(a.shoulder_comfort)<5)).length>=4; }}
]; }
function fitCheckMilestones(){ const s=fitState(); if(!s) return; let ch=false; fitMilestoneDefs().forEach(m=>{ if(!s.milestones[m.key]&&m.test()){ s.milestones[m.key]=new Date().toISOString(); ch=true; } }); if(ch) fitSave(s); }
function fitProteinStreak(){ const t=getState().nutritionTargets.protein; if(!t) return 0; const by={}; getState().meals.forEach(m=>{ by[m.dateKey]=(by[m.dateKey]||0)+Number(m.protein||0); }); let n=0; const d=new Date(); if((by[localDateKey(d)]||0)<t) d.setDate(d.getDate()-1); while((by[localDateKey(d)]||0)>=t){ n++; d.setDate(d.getDate()-1); } return n; }
function fitProteinDays(n=7){ const t=getState().nutritionTargets.protein; const by={}; getState().meals.forEach(m=>{ by[m.dateKey]=(by[m.dateKey]||0)+Number(m.protein||0); }); let hit=0; for(let i=0;i<n;i++){ const d=new Date(); d.setDate(d.getDate()-i); if(t&&(by[localDateKey(d)]||0)>=t) hit++; } return hit; }
function fitProgressMarkup(){ const s=fitState(); if(!s) return ''; fitCheckMilestones(); const t=fitWeightTrend(); const wk=fitRunLogs(7), all=fitRunLogs(null); const longest=Math.max(0,...all.map(l=>Number(l.continuous)||0)); const out=fitRaceOutlook(); const hikeMax=Math.max(0,...getState().history.flatMap(h=>(h.logs||[]).filter(l=>l.type==='ruck').map(l=>Number(l.minutes)||0))); const arch=getState().archery.filter(a=>+new Date(a.date||a.createdAt||0)>=Date.now()-28*864e5).length; const ms=fitMilestoneDefs();
  const chart=t.weeks.length>=2?lineChart(t.weeks.map(w=>({date:w.date,value:w.avg})),' lb','weekly average weight'):'<p class="note">Two weeks of weigh-ins and the weekly-average line appears.</p>';
  return `<section class="card"><div class="kicker">15K &amp; RUNNING</div><div class="progress-summary"><div class="stat"><strong>${wk.length}</strong><small>runs this week</small></div><div class="stat"><strong>${wk.reduce((a,l)=>a+(Number(l.minutes)||0),0)}</strong><small>min this week</small></div><div class="stat"><strong>${longest||'—'}</strong><small>longest nonstop · min</small></div></div><p class="note" style="margin:6px 0 0">Step ${s.run.step} · ${FIT_RUN_STEPS[s.run.step-1].label}. ${all.length} run/walk sessions logged${all.length?`, ${Math.round(all.reduce((a,l)=>a+(Number(l.distance)||0),0)*10)/10} mi by hand`:''}. ${out?esc(out.line):'No race date yet.'}</p></section>
  <section class="card"><div class="kicker">WEIGHT · WEEKLY AVERAGE</div>${chart}<p class="note" style="margin:6px 0 0">${t.rate===null?'':`Last week ${t.rate>0?'+':''}${t.rate} lb. `}Goal ${s.profile.goalWeight} lb at 1–1.5 lb a week. ${t.fastWeeks>=2?'Dropping faster than that for two-plus weeks: review fueling and recovery.':''}</p></section>
  <section class="card"><div class="kicker">ADHERENCE · LAST 7 DAYS</div><div class="progress-summary"><div class="stat"><strong>${fitProteinDays(7)}/7</strong><small>protein days</small></div><div class="stat"><strong>${hikeMax||'—'}</strong><small>longest hike · min</small></div><div class="stat"><strong>${arch}</strong><small>bow sessions · 4 wks</small></div></div></section>
  <section class="card"><div class="kicker">MILESTONES</div><p class="note" style="margin:6px 0 8px">Process wins, no dates promised.</p>${ms.map(m=>`<div class="weight-row"><div><strong>${esc(m.label)}</strong><small>${s.milestones[m.key]?`done ${new Date(s.milestones[m.key]).toLocaleDateString()}`:'not yet'}</small></div><span>${s.milestones[m.key]?'✓':'·'}</span></div>`).join('')}</section>`; }

// ---------- settings / plan ----------
function fitSettingsMarkup(){ const s=fitState(); if(!s) return ''; const p=s.profile; const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
  return `<div class="setting"><label>Training plan</label><select id="fitPlan"><option value="hunter" ${s.plan==='hunter'?'selected':''}>Hunter program (8-week, as before)</option><option value="run15k" ${s.plan==='run15k'?'selected':''}>15K run/walk + Strength A/B (two-week starter)</option></select><p class="note" style="margin:4px 0 0">The 15K plan starts from a quarter-mile base: easy jog/walk intervals, two short strength days, a recovery day, and optional hunt conditioning. It never assumes you can run 15K today.</p></div>
  <div class="setting"><label>Race</label><div class="set-grid"><div class="field"><label>Race date</label><input id="fitRaceDate" type="date" value="${p.race.date||''}"></div><div class="field"><label>Goal</label><select id="fitRaceMode"><option value="runwalk" ${p.race.mode!=='continuous'?'selected':''}>Finish safely, run/walk is fine</option><option value="continuous" ${p.race.mode==='continuous'?'selected':''}>Aim for a continuous run</option></select></div></div><p class="note" style="margin:4px 0 0">${p.race.window||'January–February 2027'} · ${p.race.distanceKm} km (${p.race.distanceMi} mi). Leave the date blank until you pick the event.</p></div>
  <div class="setting"><label>Body</label><div class="set-grid three"><div class="field"><label>Height (in)</label><input id="fitHeight" inputmode="numeric" value="${p.heightIn||''}"></div><div class="field"><label>Goal weight (lb)</label><input id="fitGoalW" inputmode="decimal" value="${p.goalWeight||''}"></div><div class="field"><label>Protein target (g)</label><input id="fitProtein" inputmode="numeric" value="${getState().nutritionTargets.protein||''}"></div></div><div class="set-grid"><div class="field"><label>Hydration target (servings)</label><input id="fitHydra" inputmode="numeric" value="${s.hydration.target}"></div><div class="field"><label>Loss guideline (lb/week)</label><input id="fitLoss" value="${p.lossMin}–${p.lossMax}" disabled></div></div></div>
  <div class="setting"><label>Meal times</label><div class="set-grid">${s.mealSlots.map((sl,i)=>`<div class="field"><label>${esc(sl.label)}</label><input id="fitSlot${i}" type="time" value="${sl.time}"></div>`).join('')}</div></div>
  <div class="setting"><label>Training days (15K plan)</label>${days.map(d=>`<div class="fit-dayrow"><span>${d.slice(0,3)}</span><select id="fitDay${d}">${Object.entries(FIT_DAY_TYPES).map(([k,v])=>`<option value="${k}" ${s.days[d]===k?'selected':''}>${v}</option>`).join('')}</select></div>`).join('')}<p class="note" style="margin:4px 0 0">Keep at least one recovery or rest day. Don't stack two run days back to back if the shins complain.</p></div>
  <div class="setting"><label>Preferred foods (one per line)</label><textarea id="fitFoods" rows="5">${esc(s.foods.join('\n'))}</textarea></div>
  <div class="setting"><label>Reminders</label><label class="check-row"><input type="checkbox" id="fitReminders" ${s.reminders?'checked':''}><span>Remind me at meal times while the app is open (asks for notification permission once). No server, no push.</span></label></div>
  <div class="setting"><label>Seed data</label><p class="note" style="margin:0 0 8px">Import <code>USER_SEED_DATA.json</code> to fill blanks. It never overwrites a value you've set, and importing twice changes nothing.</p><button class="secondary" style="width:100%" onclick="$('#fitSeedInput').click()">IMPORT SEED JSON</button><input id="fitSeedInput" type="file" accept="application/json" hidden onchange="fitImportSeed(this.files[0])"></div>`; }
function fitSaveSettings(){ const s=fitState(); if(!s||!$('#fitPlan')) return; const was=s.plan; s.plan=$('#fitPlan').value; s.profile.race.date=$('#fitRaceDate').value||null; s.profile.race.mode=$('#fitRaceMode').value; s.profile.heightIn=+$('#fitHeight').value||s.profile.heightIn; s.profile.goalWeight=+$('#fitGoalW').value||s.profile.goalWeight; s.hydration.target=+$('#fitHydra').value||8; s.mealSlots.forEach((sl,i)=>{ const v=$(`#fitSlot${i}`)?.value; if(v) sl.time=v; }); ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].forEach(d=>{ const v=$(`#fitDay${d}`)?.value; if(v) s.days[d]=v; }); s.foods=$('#fitFoods').value.split('\n').map(x=>x.trim()).filter(Boolean); const rem=$('#fitReminders').checked; if(rem&&!s.reminders) fitRequestNotify(); s.reminders=rem; if(was!=='run15k'&&s.plan==='run15k'&&!s.run.stepSince) s.run.stepSince=localDateKey(); fitSave(s); const t=getState().nutritionTargets; const pv=+$('#fitProtein').value; if(pv){ t.protein=pv; STORE.set('hr30_nutritionTargets',t); } }
function fitRequestNotify(){ try{ if('Notification' in window&&Notification.permission==='default') Notification.requestPermission(); }catch{} }
let fitReminderTimer=null;
function fitScheduleReminders(){ clearInterval(fitReminderTimer); const s=fitState(); if(!s||!s.reminders) return; let fired={}; fitReminderTimer=setInterval(()=>{ try{ if(!('Notification' in window)||Notification.permission!=='granted') return; const now=new Date(); const hm=`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`; const k=localDateKey()+hm; s.mealSlots.forEach(sl=>{ if(sl.time===hm&&!fired[k+sl.key]&&!fitSlotLogged(sl.key).length){ fired[k+sl.key]=1; new Notification('HUNT READY 30',{body:`${sl.label} · ${fitClock(sl.time)}. Log it when it's down.`}); } }); }catch{} },30000); }
// Merge-only seed import. Fills blanks; lists what it would change; confirms; idempotent.
async function fitImportSeed(file){ if(!file) return; try{ const d=JSON.parse(await file.text()); if(d.app!=='Hunt Ready 30'||!d.profile) throw new Error('Not a Hunt Ready 30 seed file.'); const s=fitState()||fitDefaults(); const changes=[]; const set=(obj,key,val,label)=>{ if(val===undefined||val===null||val===''||Array.isArray(val)&&!val.length) return; const cur=obj[key]; if(cur===undefined||cur===null||cur===''||cur===0||(Array.isArray(cur)&&!cur.length)){ obj[key]=val; changes.push(label); } };
    set(s.profile,'heightIn',d.profile.height_inches,'height'); set(s.profile,'startWeight',d.profile.starting_weight_lb_approx,'starting weight'); set(s.profile,'goalWeight',d.profile.goal_weight_lb,'goal weight'); if(d.profile.race){ set(s.profile.race,'date',d.profile.race.exact_date,'race date'); set(s.profile.race,'window',d.profile.race.target_window,'race window'); }
    const t=STORE.get('hr30_nutritionTargets',{}); let tc=false; [['calories','estimated_calories_daily_initial'],['protein','protein_target_g_daily_initial'],['carbs','estimated_carbs_g_daily'],['fat','estimated_fat_g_daily']].forEach(([k,sk])=>{ if(!Number(t[k])&&d.nutrition&&Number(d.nutrition[sk])){ t[k]=Number(d.nutrition[sk]); tc=true; changes.push(k+' target'); } });
    if(d.nutrition&&Array.isArray(d.nutrition.meals)){ d.nutrition.meals.forEach(m=>{ const key=m.slot==='protein_shake_1'?'shake1':m.slot==='protein_shake_2'?'shake2':m.slot; const sl=s.mealSlots.find(x=>x.key===key); if(sl&&!sl.userSet&&sl.time!==m.time){ sl.time=m.time; changes.push(`${sl.label} time`); } }); }
    if(d.nutrition&&Array.isArray(d.nutrition.preferred_foods)){ d.nutrition.preferred_foods.forEach(f=>{ if(!s.foods.some(x=>x.toLowerCase()===String(f).toLowerCase())){ s.foods.push(f); changes.push('food: '+f); } }); }
    if(Array.isArray(d.training_week_1)){ d.training_week_1.forEach(x=>{ const map={run_walk:'run_walk',strength_A:'strength_A',strength_B:'strength_B',recovery:'recovery',long_run_walk:'long_run_walk',optional_hunt_conditioning:'hunt_conditioning'}; const v=map[x.type]; if(v&&!s.days[x.day]){ s.days[x.day]=v; changes.push(x.day+' session'); } }); }
    const norm=v=>String(v||'').toLowerCase().replace(/\(.*?\)/g,'').replace(/[^a-z0-9]/g,''); const same=(a,b)=>{ a=norm(a); b=norm(b); return !!a&&!!b&&(a===b||a.includes(b)||b.includes(a)); };
    const addSupp=(name,kind,status,extra={})=>{ if(s.supps.some(x=>same(x.name,name))||s.hydration.products.some(p=>same(p.name,name))) return; s.supps.push({id:uid(),name,kind,status,dose:'',unit:'',schedule:kind==='investigational'?'':'daily',note:'',taken:{},...extra}); changes.push(name); };
    (d.supplements_user_reported||[]).forEach(x=>addSupp(x.name,'supplement',x.status==='user_reported_current'?'current':x.status||'interested'));
    (d.medications_and_investigational_substances||[]).forEach(x=>{ const inv=x.approved===false||/retatrutide|tesamorelin|ipamorelin|bpc|tb-500|cjc/i.test(x.name); if(inv) addSupp(x.name,'investigational',x.status==='excluded_by_user'?'excluded':/hold/.test(x.status||'')?'on_hold':/not_active/.test(x.status||'')?'not_active':'considering',{note:'Investigational. No dose or schedule stored.'}); else addSupp(x.name,'medication','user_reported',{concentration:x.concentration_mg_per_ml,weeklyMlMin:x.weekly_volume_ml_range?.[0],weeklyMlMax:x.weekly_volume_ml_range?.[1],schedule:(x.user_reported_days||[]).map(q=>q.slice(0,3)).join('/')||'',confirmed:false,note:x.note||'Tracking only.'}); });
    if(!changes.length){ alert('Nothing to import: every seed value is already set.'); return; }
    if(!confirm(`Import will fill ${changes.length} blank value${changes.length===1?'':'s'}:\n\n${[...new Set(changes)].slice(0,20).join(', ')}${changes.length>20?'…':''}\n\nNothing you already set will change. Continue?`)) return;
    fitSave(s); if(tc) STORE.set('hr30_nutritionTargets',t); closeModal(); renderToday(); alert('Seed data merged.'); }catch(e){ alert('Import failed: '+e.message); } finally{ const i=$('#fitSeedInput'); if(i) i.value=''; } }
